        resp = self.req(text='Pat: hi', runner=r, dryRun=False)
        self.assertTrue(resp['sent'], resp)
        self.assertIn('no contacts', self.req(text='Pat: hi', runner=r, dryRun=False, relayAll=False)['error'])


